using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Text.RegularExpressions;
using System.Windows.Forms;
internal sealed class BrandLogo : Control
{
    public string Brand;
    static readonly Dictionary<string,string> Data = new Dictionary<string,string> {
        { "lenovo", "" },
        { "amd", "" },
        { "arm", "" },
        { "dell", "" },
        { "qualcomm", "" },
        { "asus", "" },
        { "hp", "" },
        { "samsung", "" },
        { "acer", "" },
        { "intel", "" },
        { "nvidia", "" }
    };
    static readonly Dictionary<string,Bitmap> Cache = new Dictionary<string,Bitmap>();
    public BrandLogo(string brand) { Brand=brand; Width=125; Height=62; Margin=new Padding(0,0,0,10); AccessibleName="Logo "+brand; SetStyle(ControlStyles.UserPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.AllPaintingInWmPaint,true); }
    internal static string Resolve(string manufacturer)
    {
        string text=(manufacturer??"").ToLowerInvariant();
        if(text.Contains("hewlett") || text.Contains("h-p")) return "hp";
        foreach(string key in Data.Keys) if(Regex.IsMatch(text,@"(?<![a-z0-9])"+Regex.Escape(key)+@"(?![a-z0-9])")) return key;
        if(text.Contains("advanced micro devices"))return "amd";
        return null;
    }
    internal static Bitmap Get(string brand)
    {
        Bitmap image;
        if(Cache.TryGetValue(brand,out image)) return image;
        using(var stream=new MemoryStream(Convert.FromBase64String(Data[brand])))
        using(var decoded=new Bitmap(stream)) image=new Bitmap(decoded);
        Cache[brand]=image; return image;
    }
    protected override void OnPaint(PaintEventArgs e)
    {
        base.OnPaint(e); var image=Get(Brand); float scale=Math.Min((Width-12f)/image.Width,(Height-12f)/image.Height);
        var box=new RectangleF(6,(Height-image.Height*scale)/2,image.Width*scale,image.Height*scale);
        e.Graphics.InterpolationMode=System.Drawing.Drawing2D.InterpolationMode.HighQualityBicubic;e.Graphics.DrawImage(image,box);
    }
}
